int main(int argc, char *argv[]) {
    // 检查命令行参数
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <command> [args...]\n", argv[0]);
        return 1;
    }
    // 若 argv[1] 以 "/" 开头，则直接使用该路径
    // 否则在 PATH 中找到第一个存在且可执行的命令路径
    static char full_path[PATH_MAX];
    char       *command_path = argv[1];

    if (command_path[0] != '/') {
        char *path_env = getenv("PATH");
        if (path_env) {
            char *paths = strdup(path_env);
            char *save  = NULL;
            // 遍历 PATH 中的每个目录，找到第一个存在且可执行的命令路径
            for (char *dir = strtok_r(paths, ":", &save); dir; dir = strtok_r(NULL, ":", &save)) {
                int n = snprintf(full_path, sizeof(full_path), "%s/%s", dir, command_path);
                if (n > 0 && (size_t)n < sizeof(full_path) && access(full_path, X_OK) == 0) {
                    command_path = full_path;
                    break;
                }
            }
            free(paths);
        }
    } // 找到 command_path 后，继续执行

    // 初始化统计结构体
    syscall_stats stats = {0};
    // 使用管道和子进程通信
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    } // 创建管道后，父进程将读取 strace 输出，子进程将 strace 输出写入管道
    // pipefd[0] 是父进程读取端，pipefd[1] 是子进程写入端
    // 单向通信

    // 准备 strace 命令参数
    // 1. strace
    // 2. -T 参数，表示输出每个系统调用的执行时间
    // 3. -o 重定向到管道，与父进程通信
    // 4. command_path，表示要执行的命令
    // strace -T -o /dev/fd/3 command_path [args...] NULL
    size_t args      = (size_t)(argc - 2);
    size_t total     = 4 + 1 + args + 1;
    char **exec_args = calloc(total, sizeof(char *));
    if (exec_args == NULL) {
        perror("calloc");
        return 1;
    }
    size_t i       = 0;
    exec_args[i++] = "strace";
    exec_args[i++] = "-T";
    exec_args[i++] = "-o";
    exec_args[i++] = "/dev/fd/3";          // 将 strace 输出
    exec_args[i++] = (char *)command_path; // 要执行的命令
    for (size_t k = 2; k < args; k++) {
        exec_args[i++] = argv[k];
    }
    exec_args[i] = NULL; // 必须以 NULL 结尾

    // fork 一个子进程来执行 strace
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {
        // 进入子进程，执行 strace 命令
        // 从父进程继承，需要关闭管道的读取端
        close(pipefd[0]);
        // dup2 将管道写入端重定向到 fd 3，这样 strace 的输出就会写入管道
        if (dup2(pipefd[1], 3) < 0) {
            perror("dup2");
            _exit(1);
        }
        // 检查 pipefd[1] 是否为 3，如果不是，则关闭 pipefd[1]
        if (pipefd[1] != 3) {
            close(pipefd[1]);
        }
        // 使用 execve 命令，将 strace 的输出重定向到管道中
        execve("/usr/bin/strace", exec_args, environ);
        // execve 失败，打印错误信息并退出
        perror("execve");
        _exit(127);
    }
    // 父进程关闭写端，否则会导致管道无法读取到 EOF
    close(pipefd[1]);

    // 周期性地读取 strace 输出，并统计系统调用的执行时间

    // 打印统计结果

    // 若子进程结束，退出循环
    int status;
    waitpid(pid, &status, 0);
    free(exec_args);
    return 0;
}